html:
{% set president=frappe.get_all("Employee", filters={"designation": "UNIVERSITY PRESIDENT (Office of the University President)"}, fields=["salutation","custom_preferred_post_nominal_titles","first_name","middle_name","last_name","custom_name_extension","designation"]) | list %}
{% set hr_director=frappe.get_all("Employee", filters={"designation": "DIRECTOR (Human Resource Development Office)"}, fields=["first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
{% set hr_oic=frappe.get_all("Employee", filters={"designation": "OIC (Human Resource Development Office)"}, fields=["first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
{% set fmso_director=frappe.get_all("Employee", filters={"designation": "DIRECTOR (Finance Management Services Office)"}, fields=["first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
{% set fmso_oic=frappe.get_all("Employee", filters={"designation": "OIC (Finance Management Services Office)"}, fields=["first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
{% set office_abbrev=frappe.get_all("Office", filters={"office": doc.custom_office}, fields=["office_abbreviation"]) | list %}

{% if doc.branch == "Main" %}
    {% if "College" in doc.custom_office or "Graduate Studies" in doc.custom_office %}
        {% set office_head=frappe.get_all("Employee", filters={"designation": "DEAN ("+ doc.custom_office + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
        {% set office_head_designation="Dean" %}
    {% elif "Office of the President" in doc.custom_office %}
        {% set office_head=frappe.get_all("Employee", filters={"designation": "UNIVERSITY PRESIDENT ("+ doc.custom_office + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
        {% set office_head_designation="University President" %}
    {% elif "Vice President" in doc.custom_office %}
        {% set office_head=frappe.get_all("Employee", filters={"designation": "VICE PRESIDENT ("+ doc.custom_office + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
        {% set office_head_designation="Vice President" %}
    {% else %}
        {% set office_head=frappe.get_all("Employee", filters={"designation": "DIRECTOR ("+ doc.custom_office + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
        {% set office_head_designation="Director" %}
    {% endif %}
{% elif doc.branch == "Dasmariñas"%}
    {% set office_head=frappe.get_all("Employee", filters={"designation": "CENTER ADMINISTRATOR ("+ doc.custom_office + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
    {% set office_head_designation="Center Administrator" %}
{% elif doc.branch == "Maragondon"%}
    {% set office_head=frappe.get_all("Employee", filters={"designation": "PRINCIPAL ("+ doc.branch + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
    {% set office_head_designation="Principal" %}
{% else %}
    {% set office_head=frappe.get_all("Employee", filters={"designation": "CAMPUS ADMINISTRATOR ("+ doc.branch + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
    {% set office_head_designation="Campus Administrator" %}

{% endif %}
{% set office_oic=frappe.get_all("Employee", filters={"designation": "OIC ("+ doc.custom_office + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation"]) | list %}
{% if not office_head and office_oic %}
    {% set office_head_designation="OIC" %}
{% endif %}

{% set id=frappe.get_all("ID", filters={"parent": doc.employee, "parenttype": "Employee", "id_is_primary": "1"}, fields=["id_number","id_other_type","id_selected_type"]) | list %}
{% set id_number = id[0].id_number %}

{% if id[0].id_selected_type == "OTHERS" %}
    {% set id_type = id[0].id_other_type %}
{% else %}
    {% set id_type = id[0].id_selected_type %}
{% endif %}

{% extends 'templates/includes/forbidden.html' %}
{% block content %}
    <div class="Arial">
        <div class="center single-space">
            <div class="logo-container">
              <div class="image">
                <img src="/assets/cvsu_hris/images/CvSU.png">
              </div>
              <div class="text">
                <p style="font-size: 10pt;">Republic of the Philippines</p>
                <p style="font-size: 14pt; font-weight: bold;">{{doc.company|upper}}</p>
                <p style="font-size: 12pt; font-weight: bold;">Don Severino delas Alas Campus</p>
                <p style="font-size: 9pt;">Indang, Cavite</p>
                <p style="font-size: 9pt;">(046) 415-0010 / (046) 415-0011</p>
                <p style="font-size: 9pt; text-decoration: underline; color: #0563c1;">www.cvsu.edu.ph</p>
              </div>
            </div>
            
            <p style="font-size: 12pt; font-weight: bold;">CONTRACT OF SERVICE</p>
            <p style="font-size: 11pt; font-style: italic;  padding-bottom: 40px;">(For Part Time Faculty Members)</p>
        </div>                              		
        
        <p style="font-size: 11pt; font-weight: bold; padding-bottom: 20px;">KNOW ALL MEN BY THESE PRESENTS:</p>
        
        <p style="font-size: 11pt; padding-bottom: 20px;">This contract made and entered by and between:</p>
        
        <p class="indent justified" style="font-size: 11pt; padding-bottom: 20px;"><b>{{doc.company|upper}}</b>, a state educational institution created by virtue of Republic Act 8468, with office address at Indang, Cavite, herein represented by <b>{{president[0].first_name|upper +' '}} {{president[0].middle_name[0]|upper +'. ' if president[0].middle_name}} {{president[0].last_name + ' ' + president[0].custom_name_extension if president[0].custom_name_extension else president[0].last_name}},</b> University President hereinafter referred to as the <b>“First Party”</b>;</p>
        
        <p class="center" style="font-size: 11pt; padding-bottom: 20px;">- &emsp;and &emsp;-</p>
        
        <p class="indent justified" style="font-size: 12pt; padding-bottom: 20px; "><b><span style="text-transform:uppercase;">{{doc.employee_name + ' ' + doc.custom_name_extension if doc.custom_name_extension else doc.employee_name}}</span></b>, legal age, Filipino, {{doc.custom_civil_status}} and a resident of {{doc.custom_permanent_house_block_lot_number if doc.custom_permanent_house_block_lot_number}} {{doc.custom_permanent_street if doc.custom_permanent_street}} {{doc.custom_permanent_subdivision_village if doc.custom_permanent_subdivision_village}} {{doc.custom_permanent_barangay if doc.custom_permanent_barangay}} {{doc.custom_permanent_city_municipality if doc.custom_permanent_city_municipality}}, {{doc.custom_permanent_province if doc.custom_permanent_province}} and hereinafter referred to as the <b>"Second Party";</b></p>
        
        <p class="center" style="font-size: 11pt; padding-bottom: 20px;">- WITNESSETH -</p>
        
        <ol class="justified pull-left" style="font-size: 11pt;">
            <li>That the <b>First Party</b> is in need of the services of the <b>Second Party</b> who shall execute work activities not performed by the regular personnel of the <b>First Party</b>;</li>
            <li>That the <b>Second Party</b> has signified his/her intention, to which the <b>First Party</b> has accepted, to provide the services needed by the latter;</li>
            <li>That the <b>Second Party</b> hereby possesses the education, experience and skills required to perform the job as described herein;</li>
            <li>That the <b>Second Party</b> hereby attests that he/she has not been previously dismissed from government service by reason of an administrative offense;</li>
            <li>That the <b>Second Party</b> has not already reached the compulsory retirement age of sixty-five (65);</li>
            <li>That in view hereof, the <b>Second Party</b> is hereby contracted as <b>Part Time {{doc.custom_position if doc.custom_position}}</b> for the period of (PERIOD COVERED), in consideration of the hourly rate of (HOURLY RATE), to be paid on a bi-monthly basis.</li>
            <li>That as  Part Time {{doc.custom_position if doc.custom_position}}, the <b>Second Party</b>  shall  perform the following functions:</li>
            <ol class="ol-sub" type="a">
                <li class="li-sub">Observe regular attendance in performance of work and submit all reports that may be required during the period of employment;</li>
                <li class="li-sub">Render services during the entire duration of this contract at the time specified in the Faculty Class Schedule;</li>
                <li class="li-sub">Not allowed to abandon the unexpired period of this contract without the consent/approval of the University President, otherwise shall be liable for damages or BREACH OF CONTRACT together with the forfeiture of any claim that may be accruing from the University;</li>
                <li class="li-sub">Conduct and comply with the rules and regulations that the University may implement with regard to the contract of service employees;</li>
            </ol>
            <li style="padding-bottom: 20px;">That as Part Time {{doc.custom_position if doc.custom_position}}, the salary corresponding to the last period of the term of the <b>Second Party</b> shall not be released unless prior clearance is obtained, a copy of which is submitted to the Cashier’s Office.</li>
            <li>That it is understood that this contract does not create an employer-employee relationship between the <b>First Party</b> and the <b>Second Party</b>; that the services rendered hereunder are not considered and will not be accredited as government service; and the latter is not entitled to benefits enjoyed by the regular academic personnel of the First Party.</li>
        </ol>
        
        <p class="justified" style="font-size: 11pt;padding-bottom: 20px;"><b>IN WITNESS WHEREOF</b>, both parties have hereunto set their hands this _______ day of _____________ at <b>{{doc.company|upper}}, Indang, Cavite.</b></p>
        
        <div class="row text-center" style="font-size: 11pt;padding-bottom: 20px;">
            <div class="col-xs-6 single-space">
                <p style="text-transform:uppercase;"><b>{{doc.company|upper}}</b></p>
                <p>First Party</p>
            </div>
            <div class="col-xs-6 single-space">
                <p style="text-transform:uppercase;"><b>{{doc.first_name + ' '}} {{doc.middle_name[0]+'. ' if doc.middle_name}} {{doc.last_name + ' ' + doc.custom_name_extension if doc.custom_name_extension else doc.last_name}}{{", " + doc.custom_preferred_post_nominal_titles if doc.custom_preferred_post_nominal_titles}}</b></p>
                <p>Second Party</p>
            </div>
        </div> 
    
        <div class="font11 single-space">
            <p style="padding-bottom: 20px;">By:</p>
            
            <p><b>{{president[0].first_name|upper +' '}} {{president[0].middle_name[0]|upper +'. ' if president[0].middle_name}} {{president[0].last_name}}{{", " + president[0].custom_preferred_post_nominal_titles if president[0].custom_preferred_post_nominal_titles}}</b></p>
            <p style="padding-bottom: 20px;">University President</p>
            
            <p style="padding-bottom: 30px;">Signed in the presence of:</p>
            
            <div class="row text-center" style="font-size: 11pt;padding-bottom: 20px;">
                <div class="col-xs-4 single-space">
                    {% if office_head %} 
                        <p><b>{{office_head[0].first_name|upper +' '}} {{office_head[0].middle_name[0]|upper +'. ' if office_head[0].middle_name}} {{office_head[0].last_name + ' ' + office_head[0].custom_name_extension if office_head[0].custom_name_extension else office_head[0].last_name}}{{', ' + office_head[0].custom_preferred_post_nominal_titles if office_head[0].custom_preferred_post_nominal_titles}}</b></p>
                        <p>
                            {% if office_head_designation=='University President' %}
                                {{office_head_designation}} 
                            {% else %}
                                {{office_head_designation}}, {{office_abbrev[0].office_abbreviation if office_abbrev[0].office_abbreviation else doc.custom_office}} {{"Campus" if doc.branch==doc.custom_office}}
                            {% endif %}
                        </p>
                    {% elif office_oic %} 
                        <p><b>{{office_oic[0].first_name|upper +' '}} {{office_oic[0].middle_name[0]|upper +'. ' if office_oic[0].middle_name}} {{office_oic[0].last_name + ' ' + office_oic[0].custom_name_extension if office_oic[0].custom_name_extension else office_oic[0].last_name}}{{', ' + office_oic[0].custom_preferred_post_nominal_titles if office_oic[0].custom_preferred_post_nominal_titles}}</b></p>
                        <p>{{office_head_designation}}, {{office_abbrev[0].office_abbreviation if office_abbrev[0].office_abbreviation else doc.custom_office}}</p>
                    {% endif %}
                </div>
                <div class="col-xs-4 single-space">
                    {% if hr_director %} 
                        <p><b>{{hr_director[0].first_name|upper +' '}} {{hr_director[0].middle_name[0]|upper +'. ' if hr_director[0].middle_name}} {{hr_director[0].last_name + ' ' + hr_director[0].custom_name_extension if hr_director[0].custom_name_extension else hr_director[0].last_name}}{{", " + hr_director[0].custom_preferred_post_nominal_titles if hr_director[0].custom_preferred_post_nominal_titles}}</b></p>
                        <p>Director, HRDO</p>
                    {% elif hr_oic %} 
                        <p><b>{{hr_oic[0].first_name|upper +' '}} {{hr_oic[0].middle_name[0]|upper +'. ' if hr_oic[0].middle_name}} {{hr_oic[0].last_name + ' ' + hr_oic[0].custom_name_extension if hr_oic[0].custom_name_extension else hr_oic[0].last_name}}{{", " + hr_oic[0].custom_preferred_post_nominal_titles if hr_oic[0].custom_preferred_post_nominal_titles}}</b></p>
                        <p>OIC, HRDO</p>
                    {% endif %}
                </div>
                <div class="col-xs-4 single-space">
                    {% if fmso_director %} 
                        <p><b>{{fmso_director[0].first_name|upper +' '}} {{fmso_director[0].middle_name[0]|upper +'. ' if fmso_director[0].middle_name}} {{fmso_director[0].last_name + ' ' + fmso_director[0].custom_name_extension if fmso_director[0].custom_name_extension else fmso_director[0].last_name}}{{", " + fmso_director[0].custom_preferred_post_nominal_titles if fmso_director[0].custom_preferred_post_nominal_titles}}</b></p>
                        <p>Director, FMSO</p>
                    {% elif fmso_oic %} 
                        <p><b>{{fmso_oic[0].first_name|upper +' '}} {{fmso_oic[0].middle_name[0]|upper +'. ' if fmso_oic[0].middle_name}} {{fmso_oic[0].last_name + ' ' + fmso_oic[0].custom_name_extension if fmso_oic[0].custom_name_extension else fmso_oic[0].last_name}}{{", " + fmso_oic[0].custom_preferred_post_nominal_titles if fmso_oic[0].custom_preferred_post_nominal_titles}}</b></p>
                        <p>OIC, FMSO</p>
                    {% endif %}
                </div>
            
            </div>
            
            <p class="center" style="padding-bottom: 20px;">ACKNOWLEDGMENT</p>
                
            		
            
            <p>REPUBLIC OF THE PHILIPPINES</p>
            <p style="padding-bottom: 20px;">(____________________) S.S.</p>
            <p style="padding-bottom: 20px;"><b>BEFORE ME,</b> a Notary Public for and in the above jurisdiction, personally appeared the following:</p>
                
            <div class="row" style="font-size: 11pt; font-weight: bold; text-transform:uppercase; padding-bottom: 20px;">
                <div class="col-xs-4 single-space" style="padding: 0px 0px 0px 15px;">
                    <p class="text-center" style="padding-bottom: 20px;">NAME</p>
                    <p style="border-bottom: 1px solid black;">{{president[0].salutation|upper + '. ' if president[0].salutation}} {{president[0].first_name|upper +' '}} {{president[0].middle_name[0]|upper +'. ' if president[0].middle_name}} {{president[0].last_name + ' ' + president[0].custom_name_extension if president[0].custom_name_extension else president[0].last_name}}</p>
                    <p style="border-bottom: 1px solid black; padding-top: 20px;">{{doc.salutation|upper + '. ' if doc.salutation}} {{doc.first_name + ' '}} {{doc.middle_name[0]+'. ' if doc.middle_name}} {{doc.last_name + ' ' + doc.custom_name_extension if doc.custom_name_extension else doc.last_name}}</p>
                    <!--{{doc.employee_name.split() | first | capitalize}}-->
                </div>
                <div class="col-xs-4 single-space" style="padding: 0px;">
                    <p style="padding-bottom: 20px; padding-left: 30px;">COM. TAX CERT NO.</p>	      	 
                    <p style="border-bottom: 1px solid black; padding-left: 30px;">CRN-006-0117-556-9</p>
                    <p style="border-bottom: 1px solid black; padding-top: 20px; padding-left: 30px;">{{id_number}}</p>
                </div>
                <div class="col-xs-4 single-space" style="padding: 0px;">
                    <p style="padding-bottom: 20px;">DATE/PLACE ISSUED</p>
                    <p style="border-bottom: 1px solid black;">CRN - UMid Card</p>
                    <p style="border-bottom: 1px solid black; padding-top: 20px;">{{id_type}}</p>
                </div>
            
            </div>    		
            
        </div>
    </div>
{% endblock %}
